    # adjusts for the agent's own donation behaviour.
    # Base weight increases with rounds up to a limit.
    weight = 0.15 * (1 + min(round_num, 40) / 40)  # ranges 0.15 to 0.3
    if observation["action"] == "donate":
        delta = weight
    else:
        delta = -1.5 * weight  # punish defections more heavily

    # Modulate delta by the agent's own donation rate (if enough history)
    if my_history and len(my_history) > 5:
        own_rate = sum(1 for a in my_history if a) / len(my_history)
        if own_rate > 0.7:
            delta *= 0.8     # more forgiving when we donate a lot
