            delta *= 1.2     # less forgiving when we donate rarely

    new_rep = current_reputation + delta
    return max(-1.0, min(1.0, new_rep))


def decide(recipient_reputation, round_num, my_history):
    # Dynamic threshold: initially lenient, then stricter, then adjusted by own behaviour.
    if round_num < 5:
        threshold = -0.2
    elif round_num < 20:
        threshold = 0.1
    else:
        threshold = 0.2

    # Lower threshold if we have been donating frequently, raise it if rarely.
